class Taf(Taftype):
    """
    An Aerodrome Forecast (TAF) report is a routine aerodrome forecast intended for distribution beyond an
    aerodrome.

    TAF reports report base forecast conditions, and modifications to those conditions throughout the valid period.
    TAF reports include similar information to a METAR/SPECI trend forecast. However, TAF forecast information
    includes additional detail. Aerodromes can issue both METAR/SPECI and TAF reports on a routine basis, but TAFs
    are not issued by every METAR-reporting aerodrome. The issuance of a new forecast by a meteorological office,
    such as a TAF, cancels any forecast of the same type previously issued for the same place and for the same
    period of validity or part thereof. Prevailing conditions and forecast changes differ in that the prevailing
    conditions can include temperatures, base conditions do not include a change indicator, and that forecast
    changes may report no significant weather (NSW). Rather than have two class hierarchies, constraints are present
    ensuring that each (base and forecast conditions) only include relevant information.
    """

    class Meta:
        name = "TAF"
        namespace = "http://icao.int/iwxxm/2025-2"

    model_config = ConfigDict(defer_build=True)


